class DiagnosisProbe:
    def __init__(self, view, device):
        self.view, self.device = view, device

    def run_full_diagnosis(self, train_loader):
        cached = cache_at_most_ten_batches(train_loader)
        rng = local_rng(seed=42)
        original_mode = self.view.model.training
        try:
            self.view.model.eval()
            with no_grad():
                for batch in cached:
                    examples = extract_aligned_final_valid_examples(batch)
                    reference = evaluate(examples.sequences, examples.fixed_pairs)
                    for condition in supported_conditions:
                        variants, eligibility = perturb(examples, condition, rng)
                        measured = evaluate(variants, examples.fixed_pairs[eligibility])
                        record_paired_effects(reference[eligibility], measured)
        finally:
            self.view.model.train(original_mode)
        return {'metrics': aggregate_with_counts_and_nulls(),
                'metric_definitions': definitions_with_scope_and_limitations()}

 def diagnosis_interpreter_prompt(raw_diagnosis):
    return grounded_prompt(raw_diagnosis['metrics'],
                           raw_diagnosis['metric_definitions'])
